-- Full authorization/invariant matrix. Fixtures are unique users and rollback-only.
begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
do $$ declare tap_schema text; begin
 select n.nspname into strict tap_schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pgtap';
 perform set_config('search_path',format('%I, public, extensions',tap_schema),true);
end $$;
create temporary table fixture_context (a uuid default gen_random_uuid(), b uuid default gen_random_uuid(), ra uuid, rb uuid);
insert into fixture_context default values;
insert into auth.users(id) select a from fixture_context union all select b from fixture_context;
insert into nba_teams(id,name,abbreviation) values(-810000000001,'Authorization Team A','ATA'),(-810000000002,'Authorization Team B','ATB');
insert into nba_players(id,full_name) select -810000000000-n,'Authorization Player '||n from generate_series(1,12)n;
insert into nba_games(id,season,game_date,home_team_id,away_team_id,home_points,away_points)
 values('9999999810','authorization-fixture','1900-01-01',-810000000001,-810000000002,1,2);
insert into nba_player_game_stats(player_id,game_id,team_id,minutes,points,rebounds,assists,steals,blocks,turnovers)
 values(-810000000001,'9999999810',-810000000001,0,0,0,0,0,0,0);
insert into nba_dataset_imports(season,completed_at,source,dataset_version,row_counts,date_min,date_max)
 values('authorization-fixture','9999-01-01','synthetic pgTAP',gen_random_uuid()::text,'{}','1900-01-01','1900-01-03');
create function pg_temp.sqlstate(query text) returns text language plpgsql as $$
begin execute query; return '00000'; exception when others then return sqlstate; end $$;
create temporary table original_snapshot(snapshot jsonb);
grant select on fixture_context, original_snapshot to authenticated, anon;
select plan(190);
set local role authenticated;
select set_config('request.jwt.claim.sub',(select a::text from fixture_context),true);
select is(pg_temp.sqlstate($query$select public.ensure_roster()$query$), '00000', 'User A initializes roster');
select is((select public.ensure_roster()), (select public.ensure_roster()), 'Repeated initialization returns identical UUID');
set local role postgres; update fixture_context set ra=(select id from rosters where user_id=a); set local role authenticated;
